def can_rearrange(string: str) -> bool:
    from collections import Counter

    def is_valid(arr):
        for i in range(len(arr) - 1):
            if arr[i] == arr[i + 1]:
                return False
        return True

    counts = Counter(string)
    max_count = max(counts.values())

    if max_count > (len(string) + 1) // 2:
        return False

    if len(set(string)) < len(string) // 2:
        return False

    return is_valid(list(string))
```

