def last_digit_factorial_division(b, a):
    if a >= b:
        return 0
    factorial_b = 1
    for i in range(2, b + 1):
        factorial_b *= i
        if factorial_b % 10 == 0:
            factorial_b = 0
            break
    factorial_a = 1
    for i in range(2, a + 1):
        factorial_a *= i
        if factorial_a % 10 == 0:
            factorial_a = 0
            break
    return factorial_b % 10 if factorial_a else 0
