def sum_amicable_numbers(n):
    def divisors_sum(x):
        return sum(i for i in range(1, x) if x % i == 0)

    amicable_pairs = set()
    for num in range(2, n):
        partner = divisors_sum(num)
        if partner > num and divisors_sum(partner) == num:
            amicable_pairs.add(num)
            amicable_pairs.add(partner)

    return sum(amicable_pairs)
