def max_sum_divide(n):
    s = str(n)
    if len(s) == 1:
        return [0, n]

    odd_digits = []
    even_digits = []
    for i, digit in enumerate(s):
        if i % 2 == 0:
            even_digits.append(int(digit))
        else:
            odd_digits.append(int(digit))

    even_sum = sum(even_digits)
    odd_sum = sum(odd_digits)

    if even_sum > odd_sum:
        return [int(''.join(map(str, odd_digits))), int(''.join(map(str, even_digits)))]
    else:
        return [int(''.join(map(str, even_digits))), int(''.join(map(str, odd_digits)))]

# Example usage:
print(max_sum_divide(4325))  # Output: [35, 42]
```

