def longest_subsequence_with_diff_one(arr):
    if not arr:
        return 0
    arr_set = set(arr)
    max_len = 1
    for num in arr:
        if num - 1 not in arr_set:
            current_num = num
            current_len = 1
            while current_num + 1 in arr_set:
                current_num += 1
                current_len += 1
            max_len = max(max_len, current_len)
    return max_len
```

